__d(function(g,r,_i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return y}});var e,o=r(d[0]),t=r(d[1]),s=(e=t)&&e.__esModule?e:{default:e},n=r(d[2]),i=r(d[3]),l=r(d[4]),c=r(d[5]);const u='21 November 2026',p=[{h:'What we collect',p:['Account: your email address or Google account email, used only to sign you in.','Mobile number: verified once by SMS to keep fake accounts out. It is never shown to other players or used for marketing.','Face check (verification): if you want to host or join sessions, you take two live photos with your front camera (look straight, then a random action such as smiling). With your consent, these are compared automatically with your profile photo using Amazon Rekognition (Amazon Web Services, processed in Australia), and when you upload a profile photo we check that it shows a face. If the automatic result is unclear, a member of our safety team looks at the photos. The photos are deleted as soon as a decision is made; we keep only the result (verified or not) and the match score. We do not create or keep a face template, and Amazon does not store the photos or use them to train its services.','Profile: name, username, photo, bio, games, platforms, gamer ID and city that you choose to add. Your date of birth is used only to confirm you are 18+ and is never shown to anyone.','Approximate location: when you allow it, we store your location rounded to roughly 500 m. Other players only ever see an approximate distance (for example "3 km"), never your location or address. We do not collect location in the background.','Activity: requests, lobbies, chat messages, ratings, blocks and reports you create, and a push-notification token for your device.']},{h:'How we use it',p:['To show you players and sessions nearby, deliver requests and messages, send notifications you asked for, and keep the community safe (for example, reviewing reports and suspending abusive accounts).','We do not sell your data and we do not show third-party ads.']},{h:'Who can see what',p:['Other signed-in players can see your public profile (name, username, photo, bio, games, platforms, rating, verified badge) and an approximate distance. On the map you appear somewhere within a 1 km area, never at your real location. Your gamer ID is visible on your profile; leave it empty if you prefer.','Chat messages are visible only to the people in that chat. Blocked players cannot see you at all.']},{h:'Service providers',p:['We use Supabase (database, sign-in and storage), Brevo (sign-in emails), Google Firebase (phone verification SMS and push notifications), Expo (push notifications), and Google (optional Google sign-in and maps), and Amazon Web Services (automatic face check). They process data only to run the app for us.']},{h:'Your choices and rights',p:['You can edit your profile, hide yourself from Nearby, turn off location or notifications in your phone settings, and block or report anyone.','You can delete your account at any time from Profile \u2192 Delete account. This permanently removes your profile, photo, location, requests, lobbies and messages you sent.',`For any privacy request or grievance (including under India's Digital Personal Data Protection Act, 2023), email ${i.SUPPORT_EMAIL}. We respond within 30 days.`]},{h:'Retention and security',p:['We keep your data while your account is active and delete it when you delete your account, except reports and safety records we must keep to protect other users or comply with law.','Data is encrypted in transit, and access is restricted by row-level security so each user can only read what they are allowed to.']},{h:'Age',p:['Near Player is only for people aged 18 and over. We remove accounts that appear to belong to minors.']}],h=[{h:'Who can use Near Player',p:['You must be at least 18 years old and give accurate information about yourself.']},{h:'Meeting other players',p:['Near Player helps you find other gamers. We do not run, supervise or guarantee any meetup or online session, and we do not verify identities unless a profile shows a verified badge.','Meet in public places such as gaming caf\xe9s for first meetups, tell a friend your plans, and never share your address until you are comfortable. You are responsible for your own safety and your belongings.']},{h:'Rules',p:['No harassment, hate, threats, sexual content, scams, requests for money, OTPs or payment details, fake profiles, or sharing other people\'s personal information.','Do not use Near Player to sell anything, recruit for gambling, or advertise.','We may remove content, suspend or delete accounts that break these rules, including automatically when several people report the same account.']},{h:'Your content',p:['You own what you post. You give us permission to display it inside the app so it works as intended. Remove it any time by editing or deleting your account.']},{h:'Liability',p:['Near Player is provided "as is". To the extent allowed by law, we are not liable for the conduct of other users, for meetups, or for loss or damage to property.','Game and console names (such as PlayStation, Xbox or GTA) belong to their owners; Near Player is not affiliated with them.']},{h:'Changes and contact',p:[`We may update these terms; we will tell you in the app about important changes. Questions: ${i.SUPPORT_EMAIL}.`]}];function y(){const{doc:e}=(0,o.useLocalSearchParams)(),t='privacy'===e,i=t?p:h;return(0,c.jsxs)(n.Screen,{scroll:!0,edges:['bottom'],children:[(0,c.jsx)(o.Stack.Screen,{options:{title:t?'Privacy Policy':'Terms of Use',headerShown:!0}}),(0,c.jsxs)(n.Text,{variant:"caption",children:["Last updated ",u]}),i.map(e=>(0,c.jsxs)(s.default,{style:{gap:l.spacing.sm},children:[(0,c.jsx)(n.Text,{variant:"h2",children:e.h}),e.p.map((e,o)=>(0,c.jsx)(n.Text,{variant:"muted",style:{fontSize:15,lineHeight:22},children:e},o))]},e.h))]})}},773,[787,109,796,806,793,6]);